const ALL: Record<Locale, Messages> = { en, fr, ar };
export const getMessages = (l: Locale): Messages => ALL[l];
export const isDraftLocale = (l: Locale) => l !== "en";
export const DEFAULT_LOCALE: Locale = "en";

export function detectLocale(acceptLanguage: string | null): Locale {
  for (const part of (acceptLanguage ?? "").split(",")) {
    const tag = part.trim().slice(0, 2).toLowerCase();
    if (tag === "en" || tag === "fr" || tag === "ar") return tag;
  }
  return DEFAULT_LOCALE;
}
